class Solution {
public:
    int minProductSum(vector<int>& nums1, vector<int>& nums2) {
        sort(nums1.begin(), nums1.end());
        sort(nums2.rbegin(), nums2.rend());
        int sum = 0;
        for (int i = 0; i < static_cast<int>(nums1.size()); ++i) sum += nums1[i] * nums2[i];
        return sum;
    }
};
